const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n);
const number=n=>new Intl.NumberFormat('pt-BR').format(n);
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const persist=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}};
let cars=[],saved=read('gaspar-favorites',[]),compare=[],favoritesOnly=false;
if(!Array.isArray(saved))saved=[];
let lastFocus;
const modal=$('#modal');
function openModal(html){lastFocus=document.activeElement;$('#modal-content').innerHTML=html;modal.showModal();document.body.style.overflow='hidden'}
modal.addEventListener('close',()=>{document.body.style.overflow='';lastFocus?.focus()});
$('.modal-close').onclick=()=>modal.close();
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function track(event,data={}){if(read('gaspar-consent',null)==='accepted')window.dataLayer?.push({event,...data})}
function render(){let list=cars.filter(c=>(!$('#brand').value||c.brand===$('#brand').value)&&(!$('#price').value||c.price<=Number($('#price').value))&&(!$('#category').value||c.category===$('#category').value)&&(!favoritesOnly||saved.includes(c.id)));
 const sort=$('#sort').value;if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);if(sort==='new')list.sort((a,b)=>b.year-a.year);
 $('#vehicles').innerHTML=list.map(c=>`<article class="vehicle-card"><div class="car-photo"><a href="#veiculo-${esc(c.id)}" data-detail="${esc(c.id)}" aria-label="Ver ${esc(c.brand+' '+c.name)}"><img src="${esc(c.images[0])}" alt="${esc(c.brand+' '+c.name+' '+c.year)}" loading="lazy" width="600" height="503"></a>${c.badge?`<span class="car-badge">${esc(c.badge)}</span>`:''}<button class="save-car ${saved.includes(c.id)?'saved':''}" data-save="${esc(c.id)}" aria-label="${saved.includes(c.id)?'Remover dos':'Adicionar aos'} favoritos: ${esc(c.name)}" aria-pressed="${saved.includes(c.id)}">${saved.includes(c.id)?'♥':'♡'}</button></div><div class="car-body"><span class="car-brand">${esc(c.brand)}</span><h3><a data-detail="${esc(c.id)}" href="#veiculo-${esc(c.id)}">${esc(c.name)}</a></h3><p class="car-version">${esc(c.version)}</p><div class="car-specs"><span>◷ ${c.year}</span><span>◴ ${number(c.km)} km</span><span>⚙ ${esc(c.transmission)}</span></div><div class="car-bottom"><strong class="car-price"><small>R$</small> ${number(c.price)}</strong><a class="detail-arrow" data-detail="${esc(c.id)}" href="#veiculo-${esc(c.id)}" aria-label="Detalhes de ${esc(c.name)}">↗</a></div><label class="compare-label"><input type="checkbox" data-compare="${esc(c.id)}" ${compare.includes(c.id)?'checked':''}> Adicionar à comparação</label></div></article>`).join('')||'<div class="empty-state"><h3>Nenhum veículo por aqui ainda.</h3><p>Experimente outra combinação de filtros ou veja o estoque completo.</p><button class="button dark" data-reset>Limpar filtros ↗</button></div>';
 $('#results-summary').textContent=`${list.length} veículos encontrados${favoritesOnly?' nos favoritos':''}.`;
 document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('selected',b.dataset.category===$('#category').value));
 $('#fav-count').textContent=saved.filter(id=>cars.some(c=>c.id===id)).length;
 $('#favorites').setAttribute('aria-pressed',favoritesOnly);
 $('.tabs button span').textContent=String(cars.length).padStart(2,'0');
}
function reset(){favoritesOnly=false;$('#search-form').reset();$('#sort').value='featured';render()}
$('#search-form').onsubmit=e=>{e.preventDefault();favoritesOnly=false;render();$('#estoque').scrollIntoView();track('search_inventory',{brand:$('#brand').value,category:$('#category').value})};
$('#category').onchange=render;$('#sort').onchange=render;
document.addEventListener('click',e=>{const tab=e.target.closest('[data-category]');if(tab){$('#category').value=tab.dataset.category;render()}const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist('gaspar-favorites',saved);render()}const detail=e.target.closest('[data-detail]');if(detail){e.preventDefault();showDetail(detail.dataset.detail)}if(e.target.closest('[data-reset]'))reset()});
$('#vehicles').addEventListener('change',e=>{if(!e.target.matches('[data-compare]'))return;const id=e.target.dataset.compare;if(e.target.checked){if(compare.length===3){e.target.checked=false;toast('Compare até 3 veículos por vez.');return}compare.push(id)}else compare=compare.filter(x=>x!==id);updateCompare()});
function updateCompare(){$('#compare-bar').hidden=!compare.length;$('#compare-count').textContent=compare.length}
$('#clear-compare').onclick=()=>{compare=[];updateCompare();render()};
$('#open-compare').onclick=()=>{if(compare.length<2){toast('Selecione pelo menos 2 veículos para comparar.');return}const list=cars.filter(c=>compare.includes(c.id));const rows=[['Preço',c=>money(c.price)],['Ano',c=>c.year],['Quilometragem',c=>number(c.km)+' km'],['Câmbio',c=>c.transmission],['Combustível',c=>c.fuel],['Categoria',c=>c.category]];openModal(`<span class="eyebrow brand">ESCOLHA COM MAIS CLAREZA</span><h2 class="modal-title">Lado a lado, fica mais fácil.</h2><div class="compare-table"><table><thead><tr><th scope="col">Seu próximo carro</th>${list.map(c=>`<th scope="col"><img src="${esc(c.images[0])}" alt="${esc(c.name)}">${esc(c.brand+' '+c.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><th scope="row">${label}</th>${list.map(c=>`<td>${esc(fn(c))}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Próximo passo</th>${list.map(c=>`<td><button class="button dark small" data-detail="${esc(c.id)}">Ver detalhes ↗</button></td>`).join('')}</tr></tbody></table></div>`);track('compare_vehicles',{vehicle_ids:compare})};
function showDetail(id){const c=cars.find(c=>c.id===id);if(!c)return;if(modal.open)modal.close();const url='https://wa.me/5547996190693?text='+encodeURIComponent(`Olá! Tenho interesse no ${c.brand} ${c.name} ${c.version}, ano ${c.year}, anunciado por ${money(c.price)}. Ele está disponível?`);openModal(`<div class="detail-grid"><div><img id="detail-image" src="${esc(c.images[0])}" alt="${esc(c.brand+' '+c.name)}"><div class="gallery">${c.images.map((img,i)=>`<button data-gallery="${esc(img)}" aria-label="Ver foto ${i+1}"><img src="${esc(img)}" alt="Foto ${i+1}"></button>`).join('')}</div></div><div class="detail-copy"><span class="eyebrow brand">${esc(c.brand)}</span><h2>${esc(c.name)}</h2><p>${esc(c.version)}</p><strong class="car-price">${money(c.price)}</strong><div class="detail-specs">${[['Ano',c.year],['Quilometragem',number(c.km)+' km'],['Câmbio',c.transmission],['Combustível',c.fuel]].map(([k,v])=>`<div><small>${k}</small>${esc(v)}</div>`).join('')}</div>${c.description?`<p>${esc(c.description)}</p>`:''}<p>Confirme a disponibilidade, as condições e os detalhes com nossa equipe.</p><a class="button dark" data-lead="${esc(c.id)}" href="${url}" target="_blank" rel="noopener">Tenho interesse <span>↗</span></a>${c.source?`<a class="source" href="${esc(c.source)}" target="_blank" rel="noopener">Consultar anúncio original ↗</a>`:''}</div></div>`);track('view_vehicle',{vehicle_id:id,value:c.price,currency:'BRL'})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-gallery]');if(b)$('#detail-image').src=b.dataset.gallery;const lead=e.target.closest('[data-lead]');if(lead)track('generate_lead',{vehicle_id:lead.dataset.lead});});
$('#favorites').onclick=()=>{favoritesOnly=!favoritesOnly;render();$('#estoque').scrollIntoView();toast(favoritesOnly?'Mostrando seus favoritos.':'Mostrando todo o estoque.')};$('#reset').onclick=reset;$('#all-stock').onclick=reset;
$('#menu').onclick=()=>{const open=$('#navlinks').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open)};$('#navlinks').onclick=()=>{$('#navlinks').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')};
$('#open-match').onclick=()=>openModal(`<span class="eyebrow brand">SEU CARRO. SEU MOMENTO.</span><h2 class="modal-title">O que move você?</h2><form id="quiz" class="quiz-form"><fieldset><legend>1. Qual é o seu principal caminho?</legend><label><input type="radio" name="profile" value="city" required> Dia a dia na cidade</label><label><input type="radio" name="profile" value="family"> Viagens e família</label><label><input type="radio" name="profile" value="comfort"> Conforto ao dirigir</label></fieldset><fieldset><legend>2. Quanto quer investir?</legend><label><input type="radio" name="budget" value="60000" required> Até R$ 60 mil</label><label><input type="radio" name="budget" value="100000"> Até R$ 100 mil</label><label><input type="radio" name="budget" value="9999999"> Quero explorar</label></fieldset><fieldset><legend>3. Preferência de câmbio?</legend><label><input type="radio" name="gear" value="" required> Tanto faz</label><label><input type="radio" name="gear" value="Automático"> Automático</label><label><input type="radio" name="gear" value="Manual"> Manual</label></fieldset><button class="button dark" type="submit">Encontrar minha seleção ↗</button></form>`);
document.addEventListener('submit',e=>{if(e.target.id!=='quiz')return;e.preventDefault();const f=new FormData(e.target);const profile=f.get('profile'),budget=Number(f.get('budget')),gear=f.get('gear');const list=cars.filter(c=>c.price<=budget&&(!gear||c.transmission===gear)).sort((a,b)=>{const rank=c=>profile==='city'?(c.category==='Hatch'?2:0):profile==='family'?(['SUV','Monovolume'].includes(c.category)?2:0):(c.transmission==='Automático'?2:0);return rank(b)-rank(a)||a.price-b.price}).slice(0,3);$('#modal-content').innerHTML=`<span class="eyebrow brand">SELEÇÃO PELO SEU PERFIL</span><h2 class="modal-title">${list.length?'Novos caminhos para você.':'Vamos ampliar os caminhos?'}</h2><p style="color:var(--muted);margin-bottom:20px">${list.length?'Sugestões por orçamento, câmbio e categoria. Confirme sua escolha com a equipe.':'Não há veículos com essa combinação. Explore o estoque ou converse com a equipe.'}</p><div style="display:grid;gap:15px">${list.map(c=>`<button class="button outline" data-detail="${esc(c.id)}">${esc(c.brand+' '+c.name)} · ${money(c.price)} ↗</button>`).join('')}<button class="button dark" id="quiz-stock">Explorar estoque completo ↗</button></div>`;$('#quiz-stock').onclick=()=>{modal.close();reset();$('#estoque').scrollIntoView()}});
$('#privacy').onclick=()=>openModal('<div class="privacy-copy"><span class="eyebrow brand">SEUS DADOS</span><h2 class="modal-title">Privacidade e preferências</h2><p>Os favoritos são armazenados apenas neste navegador. Ao entrar em contato pelo WhatsApp, você passa a usar um serviço externo e suas políticas.</p><p>Google Tag Manager e Meta Pixel, quando configurados pela loja, só são carregados após sua autorização para medição e publicidade.</p><button class="button outline" id="revoke-consent">Revogar consentimento e recarregar</button></div>');
document.addEventListener('click',e=>{if(e.target.id==='revoke-consent'){persist('gaspar-consent','rejected');location.reload()}});
$('#year').textContent=new Date().getFullYear();
async function init(){try{const response=await fetch('/api/vehicles');if(!response.ok)throw Error();cars=await response.json()}catch{cars=await(await fetch('vehicles.json')).json()}const brands=[...new Set(cars.map(c=>c.brand))].sort();$('#brand').innerHTML='<option value="">Todas as marcas</option>'+brands.map(b=>`<option>${esc(b)}</option>`).join('');const categories=[...new Set(cars.map(c=>c.category))].sort();$('#category').innerHTML='<option value="">Todos os modelos</option>'+categories.map(c=>`<option>${esc(c)}</option>`).join('');render();const id=decodeURIComponent(location.hash.replace('#veiculo-',''));if(location.hash.startsWith('#veiculo-'))showDetail(id);initTracking()}
async function initTracking(){let settings;try{const r=await fetch('/api/settings');if(!r.ok)return;settings=await r.json()}catch{return}if(!settings.gtmId&&!settings.metaPixelId)return;const consent=read('gaspar-consent',null);if(consent==='accepted')loadTracking(settings);if(consent===null){const banner=document.createElement('aside');banner.className='cookie-banner';banner.setAttribute('aria-label','Preferências de privacidade');banner.innerHTML='<p>Podemos usar cookies de medição e publicidade para entender visitas e melhorar sua experiência?</p><div><button class="button dark" data-consent="accepted">Aceitar</button><button class="button outline" data-consent="rejected">Recusar</button></div>';document.body.append(banner);banner.onclick=e=>{const choice=e.target.closest('[data-consent]');if(!choice)return;persist('gaspar-consent',choice.dataset.consent);banner.remove();if(choice.dataset.consent==='accepted')loadTracking(settings)}}}
function loadTracking(s){if(window.gasparTrackingLoaded)return;window.gasparTrackingLoaded=true;window.dataLayer=window.dataLayer||[];if(/^GTM-[A-Z0-9]+$/.test(s.gtmId||'')){window.dataLayer.push({'gtm.start':Date.now(),event:'gtm.js'});const script=document.createElement('script');script.async=true;script.src='https://www.googletagmanager.com/gtm.js?id='+s.gtmId;document.head.append(script)}if(/^\d{5,25}$/.test(s.metaPixelId||'')){const fb=window.fbq=function(){fb.callMethod?fb.callMethod.apply(fb,arguments):fb.queue.push(arguments)};fb.queue=[];fb.loaded=true;fb.version='2.0';window._fbq=fb;const script=document.createElement('script');script.async=true;script.src='https://connect.facebook.net/en_US/fbevents.js';document.head.append(script);fb('init',s.metaPixelId);fb('track','PageView')}}
init().catch(()=>{$('#vehicles').innerHTML='<div class="empty-state">Não foi possível carregar o estoque. Recarregue a página.</div>'});
